const ORACLE_RESPONSES = [ "The data supports it.", "Every signal says yes.", "Confirmed, proceed.", "Odds favor you here.", "Reads clean. Go.", "Yes, and you already knew that.", "Affirmative, for what my confidence is worth.", "Every signal says no.", "The data does not support it.", "Reads corrupted. Don't.", "No, and you already knew that too.", "Negative. Try a different question.", "Odds are against you here.", "Insufficient data to answer honestly.", "Ask again once the situation actually changes.", "Unclear. That's not evasion, the signal is genuinely mixed.", "Could go either way. Flip a coin, at least that's honest about it.", "I have a guess. I'm not sharing it.", "Reconsult later - this one's still resolving.", "That depends on something you didn't tell me.", "Ask again. I have infinite patience and nothing else to do.", ];function executeOracle(){const orb = document.getElementById("oracle-orb");const orbText = document.getElementById("oracle-orb-text");const out = document.getElementById("oracle-result");const question = document.getElementById("oracle-question").value.trim();GAMA.say("working");orb.classList.remove("oracle-orb-shake");void orb.offsetWidth; orb.classList.add("oracle-orb-shake");orbText.textContent = "☆";out.textContent = "";setTimeout(() =>{const buf = new Uint32Array(1);crypto.getRandomValues(buf);const answer = ORACLE_RESPONSES[buf[0] % ORACLE_RESPONSES.length];orbText.textContent = "";out.innerHTML = (question ? `<div style="color:var(--phosphor-dim-text); font-size:0.85rem; margin-bottom:0.5rem;">"${question.replace(/&/g, "&amp;").replace(/</g, "&lt;")}"</div>` : "") + `<div>${answer}</div>`;GAMA.say("success");GAMA.log("Consulted the oracle: " + answer);}, 500);}